 "content": "def transform(grid):
    """Extend the periodic diagonal-color pattern encoded by the clues."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    points = [(r, c, v) for r, row in enumerate(grid)
              for c, v in enumerate(row) if v != 0]
    if not points:
        return [row[:] for row in grid]

    # Use whichever diagonal direction has the strongest repeated-line evidence.
    diff_counts = {}
    sum_counts = {}
    for r, c, _ in points:
        diff_counts[c - r] = diff_counts.get(c - r, 0) + 1
        sum_counts[c + r] = sum_counts.get(c + r, 0) + 1
    diff_score = sum(n * (n - 1) // 2 for n in diff_counts.values())
    sum_score = sum(n * (n - 1) // 2 for n in sum_counts.values())
    use_sum = sum_score > diff_score

    def index(r, c):
        return r + c if use_sum else c - r

    clues = {}
    for r, c, value in points:
        clues[index(r, c)] = value

    # Find the shortest cyclic sequence of diagonal colors consistent with
    # every non-background clue.
    period = 1
    while True:
        by_residue = {}
        consistent = True
        for offset, value in clues.items():
            residue = offset % period
            if residue in by_residue and by_residue[residue] != value:
                consistent = False
                break
            by_residue[residue] = value
        if consistent and len(by_residue) == period:
            break
        period += 1
        if period > h + w:
            # The observed clues are all preserved, with unobserved residues
            # left at background only in malformed/non-periodic inputs.
            by_residue = {offset: value for offset, value in clues.items()}
            break

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            key = index(r, c) % period
            row.append(by_residue.get(key, 0))
        out.append(row)
    return out
